mapper.select:
SELECT ID, TEMPLATE_TYPE_ID, TEMPLATE_TYPE, TEMPLATE_TYPE_NAME, CODE, BUCKET_NAME, OBJECT_NAME, STATUS FROM ( SELECT T.ID, T.TEMPLATE_TYPE_ID, TT.CODE AS TEMPLATE_TYPE, TT.NAME AS TEMPLATE_TYPE_NAME, T.CODE, T.BUCKET_NAME, T.OBJECT_NAME, T.STATUS, ROW_NUMBER() OVER ( ORDER BY
${orderBy} T.ID DESC
) RN FROM E_PRINT_TEMPLATE T LEFT JOIN E_PRINT_TEMPLATE_TYPE TT ON TT.ID = T.TEMPLATE_TYPE_ID WHERE 1 = 1
AND T.TEMPLATE_TYPE_ID = #{templateTypeId}
AND LOWER(T.CODE) LIKE '%' || LOWER(#{templateCode}) || '%'
AND T.STATUS = #{status}
) WHERE RN > #{rowStart} AND RN <= #{rowEnd} ORDER BY RN

SELECT COUNT(1)
FROM E_PRINT_TEMPLATE T
WHERE 1 = 1

    AND T.TEMPLATE_TYPE_ID = #{templateTypeId}


    AND LOWER(T.CODE) LIKE '%' || LOWER(#{templateCode}) || '%'


    AND T.STATUS = #{status}

mapper.update:
UPDATE E_PRINT_TEMPLATE
SET STATUS = 0
WHERE ID = #{id}

UPDATE E_PRINT_TEMPLATE
SET STATUS = 1
WHERE ID = #{id}

UPDATE E_PRINT_TEMPLATE
SET STATUS = #{status}
WHERE ID IN

    #{id}

mapper.delete:
DELETE FROM E_PRINT_TEMPLATE
WHERE ID IN

    #{id}
